import * as dotenv from 'dotenv';

import { untypedDb } from '@/services/supabase/untyped';
dotenv.config({ path: '.env.local' });

async function proveBomAutoIncrement() {
  console.log('\n=============================================');
  console.log('🚀 KIỂM CHỨNG CƠ CHẾ AUTO-INCREMENT BẰNG UNTYPED TRÊN DB');
  console.log('=============================================\n');

  // 1. Lấy mã BOM đầu tiên đang tồn tại trong Database
  const { data: firstBom } = await untypedDb
    .from('bom_templates')
    .select('code, tenant_id')
    .limit(1)
    .single();

  if (!firstBom) {
    console.log('Chưa có BOM nào trong DB để kiểm tra.');
    return;
  }

  // Để an toàn, chúng ta giả lập base code giống y hệt mã gốc
  // (Tức là chắc chắn mã gốc đang tồn tại)
  // Nếu baseCode đã có hậu tố, ta cứ dùng luôn làm giả thiết xấu nhất
  const baseCode = firstBom.code || 'BOM-TEST-XXX';
  const tenantId = firstBom.tenant_id;

  console.log(`[+] Mã gốc đã khóa trên hệ thống: "${baseCode}"\n`);

  let finalCode = baseCode;
  let counter = 1;
  let exists = true;

  // 2. Chạy vòng lặp chuẩn y như code API hiện tại
  while (exists) {
    console.log(`[?] Đang dùng untypedDb dò tìm mã: ${finalCode}`);
    const { data: existing, error } = await untypedDb
      .from('bom_templates')
      .select('id')
      .eq('tenant_id', tenantId)
      .eq('code', finalCode)
      .maybeSingle();

    if (error) {
      console.log('LỖI DB:', error);
      return;
    }

    if (!existing) {
      console.log(
        `✅ KẾT QUẢ: Mã "${finalCode}" TRỐNG. HOÀN TOÀN AN TOÀN ĐỂ INSERT!`,
      );
      exists = false;
      break;
    }

    console.log(
      `❌ BỊ TRÙNG! Mã "${finalCode}" đang được dùng. Đẩy hậu tố lên...`,
    );
    counter++;
    finalCode = `${baseCode}-${counter.toString().padStart(2, '0')}`;
  }

  console.log('\n=============================================');
  console.log('🎉 Bài test kết thúc tốt đẹp!');
}

proveBomAutoIncrement();

/**
 * rpc-sync.ts — Entry point
 * Chạy: tsx scripts/rpc-sync.ts
 * Hoặc: tsx scripts/rpc-sync.ts --fix   (tự sinh migration)
 */

import 'dotenv/config';
import { parseRpcCalls } from './parse-rpc-calls';
import { getDbFunctions } from './query-db-functions';
import { compareRpc, formatIssues } from './check-rpc-sync';
import { generateMigration } from './generate-migration';

const AUTO_FIX = process.argv.includes('--fix');
const SRC_DIR = process.argv.find((a) => a.startsWith('--src='))?.split('=')[1] ?? './src';

async function main() {
  console.log('\n🔍 RPC Sync Check\n' + '─'.repeat(40));

  // 1. Parse toàn bộ source code
  console.log(`📂 Scanning: ${SRC_DIR}`);
  const calls = parseRpcCalls(SRC_DIR);
  console.log(`   Found ${calls.length} rpc() call(s)\n`);

  if (calls.length === 0) {
    console.log('✅ No rpc() calls found. Nothing to check.');
    process.exit(0);
  }

  // 2. Kết nối DB và lấy danh sách functions thực tế
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.error('❌ DATABASE_URL not set in .env');
    process.exit(1);
  }

  console.log('🗄️  Querying database...');
  let dbFunctions;
  try {
    dbFunctions = await getDbFunctions(dbUrl);
    console.log(`   Found ${dbFunctions.length} function(s) in public schema\n`);
  } catch (err) {
    console.error('❌ Cannot connect to database:', (err as Error).message);
    process.exit(1);
  }

  // 3. So sánh
  const issues = compareRpc(calls, dbFunctions);

  if (issues.length === 0) {
    console.log('✅ All RPC functions are in sync with the database!\n');
    process.exit(0);
  }

  // 4. Hiển thị issues
  console.log(formatIssues(issues, calls));

  // 5. Auto-fix nếu có --fix flag
  if (AUTO_FIX) {
    console.log('\n🔧 Generating migrations...\n');
    for (const issue of issues) {
      const call = calls.find((c) => c.fnName === issue.fnName);
      if (call) {
        const filepath = generateMigration(call, issue);
        console.log(`   ✅ ${filepath}`);
      }
    }
    console.log('\n💡 Review the generated files in supabase/migrations/');
    console.log('   then run: supabase db push\n');
    process.exit(1); // vẫn exit(1) để block commit cho đến khi push migration
  } else {
    console.log('\n💡 Run with --fix to auto-generate SQL migrations\n');
    process.exit(1);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

import { createClient } from '@supabase/supabase-js';
import * as dotenv from 'dotenv';

import eastinoSeedData from '@/master-data/seed/eastino-knitting-machine.seed';

dotenv.config({ path: '.env.local' });

const supabaseUrl = process.env.VITE_SUPABASE_URL;
const supabaseKey = process.env.VITE_SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('Missing Supabase environment variables');
}

const supabase = createClient(supabaseUrl, supabaseKey);

async function run() {
  console.log('🔄 Bắt đầu import dữ liệu 18 máy EASTINO vào ncc-002...');

  // 1. Tìm supplier ncc-002
  const { data: suppliers, error: supErr } = await supabase
    .from('suppliers')
    .select('id, code, name')
    .ilike('code', '%ncc-002%');

  if (supErr) {
    console.error('❌ Lỗi khi tìm nhà cung cấp:', supErr.message);
    process.exit(1);
  }

  if (!suppliers || suppliers.length === 0) {
    console.error('❌ Không tìm thấy nhà cung cấp nào có mã chứa "ncc-002"');
    process.exit(1);
  }

  const targetSupplier = suppliers[0];
  console.log(
    `✅ Đã tìm thấy nhà cung cấp: ${targetSupplier.code} - ${targetSupplier.name}`,
  );

  // Get tenant_id from the first row in tenants, since this is a script
  const { data: tenants, error: tenantErr } = await supabase
    .from('tenants')
    .select('id')
    .limit(1);
  if (tenantErr || !tenants || tenants.length === 0) {
    console.error('❌ Không tìm thấy tenant nào trong DB');
    process.exit(1);
  }
  const tenantId = tenants[0].id;

  // 2. Map data
  const { machines } = eastinoSeedData;
  const loomsToInsert = machines.map((m, i) => {
    // Generate a unique code using SKU
    const loomCode = `LOOM-${targetSupplier.code}-${m.sku.split('-').pop()}-${i + 1}`;

    // Convert specifications
    const specs = m.specifications as Record<string, number | string | null>;

    return {
      tenant_id: tenantId,
      code: loomCode,
      name: m.name,
      loom_type: 'other', // Mặc định là 'other' vì catalog là máy dệt kim tròn
      supplier_id: targetSupplier.id,
      diameter_inch: specs?.diameter_inch ?? null,
      gauge: specs?.gauge ?? null,
      feeders: specs?.feeders ?? null,
      motor_power_kw: specs?.motor_power_kw ?? null,
      voltage: specs?.voltage ?? null,
      weight_kg: specs?.weight_kg ?? null,
      max_speed_rpm: specs?.speed_rpm ?? null,
      status: 'active',
      notes: `${m.description}\n\nĐặc điểm: ${m.features.join(', ')}`,
    };
  });

  // 3. Thực hiện insert qua rpc hoặc insert trực tiếp (bypass RLS bằng cách gọi DB function hoặc dùng service_role)
  // Nhưng vì ta dùng ANON_KEY, RLS có thể chặn insert.
  // Cách tốt nhất là dùng service_role nếu có, nhưng ở đây dùng supabase.rpc('rpc_create_loom') có thể không có.
  // Thử insert trực tiếp trước
  console.log(`📦 Đang chuẩn bị insert ${loomsToInsert.length} máy...`);

  const { data: insertedData, error: insertErr } = await supabase
    .from('looms')
    .insert(loomsToInsert)
    .select();

  if (insertErr) {
    console.error('❌ Lỗi khi insert máy:', insertErr.message);
    process.exit(1);
  }

  console.log(
    `🎉 Thành công! Đã import ${insertedData?.length || 0} máy vào hệ thống.`,
  );
}

run().catch(console.error);

import 'dotenv/config';
import postgres from 'postgres';

async function test(url: string) {
  console.log('Testing:', url);
  try {
    const sql = postgres(url, { max: 1, connect_timeout: 5, ssl: 'require' });
    const [{ now }] = await sql`SELECT now()`;
    console.log('✅ Success!', now);
    await sql.end();
  } catch (err: unknown) {
    console.log('❌ Failed:', err instanceof Error ? err.message : err);
  }
}

