import { useEffect, useRef, useCallback, useState } from 'react';
import toast from 'react-hot-toast';
import { useQuery, useQueryClient } from '@tanstack/react-query';

import { fetchUnreadCount, fetchChatRoomByEntity } from '@/api/chat.api';
import { CHAT_LABELS, type ChatMessage } from '@/schema/chat.schema';
import { playNotificationSound } from '@/shared/lib/chat-sound';
import { supabase } from '@/services/supabase/client';

// ── Unread Count Hook ──

const UNREAD_KEY = (roomId: string) => ['chat-unread', roomId] as const;

export function useUnreadCount(roomId: string | undefined) {
  return useQuery({
    queryKey: UNREAD_KEY(roomId ?? ''),
    enabled: !!roomId,
    queryFn: () => fetchUnreadCount(roomId!),
    refetchInterval: 30_000, // Poll every 30s as fallback
    staleTime: 10_000,
  });
}

// ── Portal Unread Hook (by entity ID) ──

export function usePortalChatUnread(customerId: string | undefined): number {
  const { data: room } = useQuery({
    queryKey: ['chat-room', 'customer', customerId],
    enabled: !!customerId,
    queryFn: () => fetchChatRoomByEntity('customer', customerId!),
    staleTime: 60_000,
  });

  const { data: unread = 0 } = useUnreadCount(room?.id);

  return unread;
}

// ── Mark Room as Read ──

export function useMarkAsRead(roomId: string | undefined) {
  const queryClient = useQueryClient();

  return useCallback(() => {
    if (!roomId) return;
    // Optimistically set unread to 0
    queryClient.setQueryData(UNREAD_KEY(roomId), 0);
  }, [roomId, queryClient]);
}

// ── Global Chat Notifications Hook ──
// Listens to ALL chat_messages inserts for the current user's rooms.
// Shows toast + plays sound when a new message arrives and the chat is NOT open.

export const globalOpenRooms = new Set<string>();

export function registerOpenRoom(roomId: string) {
  globalOpenRooms.add(roomId);
}

export function unregisterOpenRoom(roomId: string) {
  globalOpenRooms.delete(roomId);
}

interface UseChatNotificationsOptions {
  /** Set of room IDs currently open in a drawer — skip notifications for these */
  openRoomIds?: Set<string>;
  /** Enable sound alerts (default: true) */
  soundEnabled?: boolean;
}

export function useChatNotifications(
  options: UseChatNotificationsOptions = {},
) {
  const { openRoomIds, soundEnabled = true } = options;
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const queryClient = useQueryClient();
  const [lastMessage, setLastMessage] = useState<ChatMessage | null>(null);

  useEffect(() => {
    const channel = supabase
      .channel('global-chat-notifications')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
        },
        (payload) => {
          const msg = payload.new as ChatMessage;

          // Skip system messages
          if (msg.message_type === 'system') return;

          // Skip if this room's drawer is currently open
          if (openRoomIds?.has(msg.room_id) || globalOpenRooms.has(msg.room_id))
            return;

          // Skip own messages (sender_id matches current user)
          const userId = supabase.auth.getUser().then((r) => r.data.user?.id);
          void userId.then((uid) => {
            if (msg.sender_id === uid) return;

            setLastMessage(msg);

            // Play sound
            if (soundEnabled) {
              playNotificationSound();
            }

            // Show toast
            toast(msg.content || CHAT_LABELS.NEW_IMAGE, {
              icon: '\u{1F4AC}',
              duration: 4000,
              position: 'top-right',
              style: {
                borderRadius: '10px',
                background: 'var(--surface-strong, #1a1a2e)',
                color: 'var(--text, #fff)',
                fontSize: '0.8125rem',
                maxWidth: '320px',
              },
            });

            // Invalidate unread count for this room
            void queryClient.invalidateQueries({
              queryKey: UNREAD_KEY(msg.room_id),
            });
            // Invalidate total global unread count
            void queryClient.invalidateQueries({
              queryKey: ['chat-total-unread'],
            });
          });
        },
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      if (channelRef.current) {
        void supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [openRoomIds, soundEnabled, queryClient]);

  return { lastMessage };
}

/**
 * useCreateOrderV2
 * ==================
 * Hook tạo đơn hàng qua Supabase Edge Function.
 * Nếu Edge Function không kết nối được → tự động fallback sang direct DB insert.
 *
 * Flow:
 *   1. Gọi Edge Function create-order
 *   2. Nếu lỗi kết nối (Failed to send a request) → fallback direct insert
 *   3. Xử lý các error codes: CREDIT_BLOCKED, CREDIT_OVERDUE, CREDIT_LIMIT_EXCEEDED
 *   4. Hỗ trợ managerOverride flow (2-step confirmation)
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';

import {
  createOrder,
  getAccessToken,
  invokeCreateOrderFunction,
  fetchNextOrderNumber,
} from '@/api/orders.api';
import {
  calculateOrderTotal,
  mapOrderFormToDb,
  mapOrderItemsToDb,
  isConnectionError,
  isCreditWarning,
  isCreditBlocked,
  isStockError,
} from '@/domain/orders/OrderDomain';
import type { OrderErrorCode } from '@/domain/orders/OrderDomain';
import type { OrdersFormValues } from '@/features/orders/orders.module';

// ---------------------------------------------------------------------------
// Error types từ Edge Function
// ---------------------------------------------------------------------------

/** Alias from OrderDomain — kept for backward compat with consumers */
export type CreateOrderErrorCode = OrderErrorCode;

export { isCreditWarning, isCreditBlocked, isStockError };

export interface CreateOrderError {
  code: CreateOrderErrorCode;
  message: string;
  detail?: {
    overdueDebt?: number;
    creditLimit?: number;
    currentDebt?: number;
    orderTotal?: number;
    projectedDebt?: number;
    requireOverride?: boolean;
    stockErrors?: Array<{
      itemIndex: number;
      fabricType: string;
      requested: number;
      available: number;
    }>;
  };
}

export interface CreateOrderResult {
  ok: boolean;
  orderId: string;
  orderNumber: string;
  totalAmount: number;
  allocation: Array<{ rollId: string; rollNumber: string; meters: number }>;
  creditInfo: {
    previousDebt: number;
    newDebt: number;
    creditLimit: number;
    managerOverride: boolean;
  };
  message: string;
}

// ---------------------------------------------------------------------------
// Mutation input
// ---------------------------------------------------------------------------

export interface CreateOrderInput extends OrdersFormValues {
  /** Set true khi Manager đã xác nhận override credit warning */
  managerOverride?: boolean;
  /** Optional: ID của báo giá nguồn để liên kết */
  sourceQuotationId?: string;
}

// ---------------------------------------------------------------------------
// Kiểm tra lỗi kết nối Edge Function
// ---------------------------------------------------------------------------
// Edge Function caller
// ---------------------------------------------------------------------------

async function callCreateOrderFunction(
  input: CreateOrderInput,
  token: string,
): Promise<CreateOrderResult> {
  const payload = {
    orderNumber: input.orderNumber.trim(),
    orderType: input.orderType,
    customerId: input.customerId,
    orderDate: input.orderDate,
    deliveryDate: input.deliveryDate?.trim() || undefined,
    notes: input.notes?.trim() || undefined,
    sourceQuotationId: input.sourceQuotationId,
    managerOverride: input.managerOverride ?? false,
    items: input.items.map((item) => ({
      fabricType: item.fabricType.trim(),
      colorName: item.colorName?.trim() || undefined,
      colorCode: item.colorCode?.trim() || undefined,
      unit: item.unit ?? 'kg',
      quantity: item.quantity,
      unitPrice: item.unitPrice,
    })),
  };

  try {
    const data = await invokeCreateOrderFunction<CreateOrderResult>(
      payload,
      token,
    );
    if (!data?.ok) {
      throw {
        code: 'INTERNAL_ERROR',
        message: 'Không nhận được phản hồi từ server',
      } as CreateOrderError;
    }
    return data;
  } catch (error) {
    // Re-throw connection errors for fallback
    if (isConnectionError(error)) throw error;

    // Parse business errors from Edge Function body
    const body = (error as unknown as { context?: { body?: string } }).context
      ?.body;
    if (body) {
      try {
        const parsed = JSON.parse(body) as { error: CreateOrderError };
        if (parsed.error) throw parsed.error;
      } catch (parseErr) {
        if (parseErr && typeof parseErr === 'object' && 'code' in parseErr) {
          throw parseErr;
        }
      }
    }
    throw {
      code: 'INTERNAL_ERROR',
      message: error instanceof Error ? error.message : String(error),
    } as CreateOrderError;
  }
}

// ---------------------------------------------------------------------------
// Fallback: Direct DB insert (khi Edge Function không kết nối được)
// ---------------------------------------------------------------------------

async function createOrderDirectInsert(
  input: CreateOrderInput,
): Promise<CreateOrderResult> {
  const total = calculateOrderTotal(input.items);

  const order = await createOrder(
    mapOrderFormToDb(input, total),
    mapOrderItemsToDb(input.items),
  );

  return {
    ok: true,
    orderId: order.id,
    orderNumber: input.orderNumber.trim(),
    totalAmount: total,
    allocation: [],
    creditInfo: {
      previousDebt: 0,
      newDebt: 0,
      creditLimit: 0,
      managerOverride: false,
    },
    message: `Don hang ${input.orderNumber.trim()} da duoc tao thanh cong (direct).`,
  };
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

const QUERY_KEY = ['orders'] as const;

export function useCreateOrderV2() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateOrderInput): Promise<CreateOrderResult> => {
      // Auto-generate order number if not provided (form shows "Tự động")
      if (!input.orderNumber.trim()) {
        const nextNumber = await fetchNextOrderNumber();
        input = { ...input, orderNumber: nextNumber };
      }

      const token = await getAccessToken();

      try {
        return await callCreateOrderFunction(input, token);
      } catch (edgeFnError) {
        // Business error from Edge Function → throw for UI to handle
        if (
          edgeFnError &&
          typeof edgeFnError === 'object' &&
          'code' in edgeFnError &&
          !isConnectionError(edgeFnError)
        ) {
          throw edgeFnError;
        }

        // Connection error → fallback direct insert
        console.warn(
          '[createOrder] ⚠️ Edge Function không thể kết nối, chuyển sang direct insert.',
          edgeFnError,
        );
        return await createOrderDirectInsert(input);
      }
    },

    onSuccess: (result) => {
      void queryClient.invalidateQueries({ queryKey: QUERY_KEY });
      void queryClient.invalidateQueries({ queryKey: ['finished-fabric'] });
      void queryClient.invalidateQueries({ queryKey: ['reserve-rolls'] });
      void queryClient.invalidateQueries({ queryKey: ['customers'] });
      console.info(
        `[createOrder] ✅ ${result.orderNumber} created. ` +
          `Allocated ${result.allocation.length} rolls.`,
      );
    },

    onError: (err: Error | CreateOrderError) => {
      const code = 'code' in err ? err.code : 'UNKNOWN';
      console.error('[createOrder] ❌ Error:', code, err.message);
    },
  });
}

