/** Tính toán vị trí dropdown dựa trên trigger element */
function getDropdownStyle(triggerEl: HTMLElement): React.CSSProperties {
  const rect = triggerEl.getBoundingClientRect();
  return {
    position: 'fixed',
    top: rect.bottom + 4,
    left: rect.left,
    width: rect.width,
    zIndex: 9999,
  };
}

