  phone?: string;
  icon?: string;
  desc?: string;
};

type ComboboxProps = {
  options: ComboboxOption[];
  value?: string;
  onChange: (val: string) => void;
  onBlur?: () => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  hasError?: boolean;
  /**
   * Cho phép nhập tự do — nếu text không khớp option nào, vẫn lưu text đó làm value.
   * Khi allowInput=true, Combobox hoạt động như input có gợi ý (autocomplete).
   */
  allowInput?: boolean;
  onKeyDown?: (e: React.KeyboardEvent) => void;
  id?: string;
  /** Choose visual style based on context */
  variant?: 'default' | 'table-cell';
  /** Data density size */
  size?: 'default' | 'compact';
};

/**
 * @deprecated Use `VPEntityPicker`, `VPVirtualCombobox`, or `VPAsyncCombobox` instead.
 * This component is retained for backward compatibility but should not be used in new features.
 */
export const Combobox = memo(function Combobox({
  options,
  value,
  onChange,
  onBlur,
  placeholder = UI_LABELS.SELECT_PLACEHOLDER,
  disabled,
  className = '',
  hasError,
  allowInput = false,
  onKeyDown,
  id,
  variant = 'default',
  size = 'default',
}: ComboboxProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [dropdownStyle, setDropdownStyle] = useState<React.CSSProperties>({});
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Tính toán vị trí dropdown khi mở (position: fixed không bị ảnh hưởng bởi overflow:hidden)
  useEffect(() => {
    if (isOpen && containerRef.current) {
      setDropdownStyle(getDropdownStyle(containerRef.current));
    }
  }, [isOpen]);

  // Đóng khi click ngoài (cần check cả dropdown portal vì nằm ngoài containerRef)
  useEffect(() => {
    function handleClickOutside(event: Event) {
      if (!isOpen) return;
      const target = event.target as Node;
      const insideContainer = containerRef.current?.contains(target) ?? false;
      const insideDropdown = dropdownRef.current?.contains(target) ?? false;
      if (!insideContainer && !insideDropdown) {
        setIsOpen(false);
      }
    }
    document.addEventListener('pointerdown', handleClickOutside, {
      capture: true,
    });
    document.addEventListener('focusin', handleClickOutside, { capture: true });
    return () => {
      document.removeEventListener('pointerdown', handleClickOutside, {
        capture: true,
      });
      document.removeEventListener('focusin', handleClickOutside, {
        capture: true,
      });
    };
  }, [isOpen]);

  // Sync search với value khi allowInput
  useEffect(() => {
    if (allowInput) {
      const selected = options.find((o) => o.value === value);
      setSearch(selected ? selected.label : (value ?? ''));
    }
  }, [value, options, allowInput]);

  const filteredOptions = useMemo(() => {
    // Normalizer: lowercase and remove common separators like -, ., space, /, _
    const normalize = (s: string) => s.toLowerCase().replace(/[-. /_]/g, '');
    const q = normalize(search);
    if (!q) return options;

    return options.filter(
      (opt) =>
        normalize(opt.label).includes(q) ||
        (opt.code && normalize(opt.code).includes(q)) ||
        (opt.phone && normalize(opt.phone).includes(q)) ||
        (opt.desc && normalize(opt.desc).includes(q)),
    );
  }, [options, search]);

  const selectedOption = options.find((o) => o.value === value);

  const boxClass =
    variant === 'table-cell' ? 'table-cell-input' : 'field-input';

  const minHeightClass = className?.includes('h-')
    ? 'h-full min-h-0'
    : size === 'compact'
      ? 'min-h-[36px]'
      : 'min-h-[44px]';

  /* ── allowInput mode: render as <input> with dropdown suggestions ── */
  if (allowInput) {
    return (
      <div className={`relative ${className}`} ref={containerRef}>
        <div
          className={`${boxClass} flex items-center !p-0 ${hasError ? 'border-danger' : ''} ${disabled ? 'opacity-50' : ''} ${minHeightClass}`}
        >
          <input
            id={id}
            ref={inputRef}
            type="text"
            disabled={disabled}
            value={search}
            placeholder={placeholder}
            className={`border-none outline-none bg-transparent flex-1 px-3 focus:ring-0 ${minHeightClass}`}
            onChange={(e) => {
              setSearch(e.target.value);
              setIsOpen(true);
              // Nếu xóa hết → clear value
              if (!e.target.value) onChange('');
            }}
            onFocus={() => setIsOpen(true)}
            onBlur={() => {
              // Commit giá trị khi blur nếu có text
              if (search.trim()) {
                const searchLower = search.trim().toLowerCase();
                const match = options.find(
                  (o) =>
                    o.label.toLowerCase() === searchLower ||
                    o.value.toLowerCase() === searchLower ||
                    (o.code && o.code.toLowerCase() === searchLower),
                );
                if (match) {
                  onChange(match.value);
                  setSearch(match.label);
                } else if (filteredOptions.length === 1) {
                  const first = filteredOptions[0]!;
                  onChange(first.value);
                  setSearch(first.label);
                } else {
                  onChange(search.trim());
                }
              } else {
                onChange('');
              }
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                if (filteredOptions.length > 0) {
                  const first = filteredOptions[0]!;
                  onChange(first.value);
                  setSearch(first.label);
                  setIsOpen(false);
                }
              }
              if (e.key === 'Escape') {
                e.stopPropagation();
                if (e.nativeEvent) {
                  e.nativeEvent.stopImmediatePropagation();
                }
                setIsOpen(false);
              }
              onKeyDown?.(e);
            }}
          />
          <ChevronDown
            className="w-4 h-4 text-[var(--text-secondary)] mr-3 shrink-0 cursor-pointer"
            onClick={() => {
              setIsOpen(!isOpen);
              inputRef.current?.focus();
            }}
          />
        </div>

        {isOpen &&
          filteredOptions.length > 0 &&
          createPortal(
            <div
              ref={dropdownRef}
              style={dropdownStyle}
              className="border border-[var(--border)] rounded-lg shadow-xl max-h-[240px] overflow-y-auto bg-surface"
            >
              {filteredOptions.map((opt) => (
                <ComboboxOptionItem
                  key={opt.value}
                  opt={opt}
                  isSelected={value === opt.value}
                  onSelect={(val, label) => {
                    onChange(val);
                    setSearch(label);
                    setIsOpen(false);
                  }}
                />
              ))}
            </div>,
            document.body,
          )}
      </div>
    );
  }

  /* ── Default mode: dropdown picker only ── */
  return (
    <div className={`relative ${className}`} ref={containerRef}>
      <button
        id={id}
        type="button"
        disabled={disabled}
        onClick={() => setIsOpen(!isOpen)}
        onBlur={() => {
          if (!isOpen) onBlur?.();
        }}
        className={`${boxClass} flex items-center justify-between w-full text-left bg-surface px-3 ${minHeightClass} ${hasError ? 'border-danger' : ''} ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
        onKeyDown={(e) => {
          onKeyDown?.(e);
        }}
      >
        <span className="flex items-center gap-2 truncate pr-2">
          {selectedOption ? (
            <>
              {selectedOption.icon && (
                <Icon
                  name={selectedOption.icon as IconName}
                  size={16}
                  className="text-primary flex-shrink-0"
                />
              )}
              <span className="truncate">{selectedOption.label}</span>
            </>
          ) : (
            <span className="text-muted-foreground font-normal">
              {placeholder}
            </span>
          )}
        </span>
        <ChevronDown className="w-4 h-4 text-[var(--text-secondary)] shrink-0 ml-2" />
      </button>

      {isOpen &&
        createPortal(
          <div
            ref={dropdownRef}
            style={dropdownStyle}
            className="border border-[var(--border)] rounded-lg shadow-xl max-h-[240px] overflow-y-auto bg-surface"
          >
            <div className="sticky top-0 p-2 border-b border-[var(--border-light)] flex flex-row items-center gap-2 z-10 bg-surface">
              <Search className="w-4 h-4 text-[var(--text-secondary)]" />
              <input
                type="text"
                className="w-full text-sm outline-none bg-transparent border-none min-h-[32px]"
                placeholder={UI_LABELS.SEARCH_PLACEHOLDER}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                onClick={(e) => e.stopPropagation()}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                  }
                }}
              />
            </div>
            <div className="p-1">
              {filteredOptions.length === 0 ? (
                <div className="p-2 text-sm text-center text-[var(--text-secondary)]">
                  {UI_LABELS.NO_RESULTS}
                </div>
              ) : (
                filteredOptions.map((opt) => (
                  <ComboboxOptionItem
                    key={opt.value}
                    opt={opt}
                    isSelected={value === opt.value}
                    onSelect={(val) => {
                      onChange(val);
                      setIsOpen(false);
                      setSearch('');
                      onBlur?.();
                    }}
                  />
                ))
              )}
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
});

import {
  Controller,
  type FieldValues,
  type Path,
  type Control,
} from 'react-hook-form';

import { Combobox, type ComboboxOption } from '@/shared/components/Combobox';

/**
 * ComboboxField — eliminates repetitive Controller + Combobox boilerplate.
 *
 * Wraps react-hook-form Controller around Combobox, providing:
 *   - Type-safe field name binding
 *   - Consistent null-safe value handling
 *   - Optional label rendering
 */
type ComboboxFieldProps<T extends FieldValues> = {
  name: Path<T>;
  control: Control<T>;
  options: ComboboxOption[];
  label?: string;
  placeholder?: string;
  allowInput?: boolean;
  hasError?: boolean;
  disabled?: boolean;
};

export function ComboboxField<T extends FieldValues>({
  name,
  control,
  options,
  label,
  placeholder,
  allowInput,
  hasError,
  disabled,
}: ComboboxFieldProps<T>) {
  return (
    <div className="form-field">
      {label && <label htmlFor={name}>{label}</label>}
      <Controller
        name={name}
        control={control}
        render={({ field }) => (
          <Combobox
            options={options}
            value={(field.value as string) ?? ''}
            onChange={field.onChange}
            allowInput={allowInput}
            placeholder={placeholder}
            hasError={hasError}
            disabled={disabled}
          />
        )}
      />
    </div>
  );
}

import { clsx } from 'clsx';
import { useMemo, useState, memo } from 'react';
import type { ReactNode } from 'react';

import type { PaginatedResult } from '@/shared/types/pagination';
import { TableRowInteraction } from '@/shared/interaction';
import type { InteractionDomain } from '@/shared/interaction';

import { Icon } from './Icon';
import { EmptyState } from './EmptyState';
import { Pagination } from './Pagination';
import { TableSkeleton } from './TableSkeleton';

export interface Column<T> {
  header: ReactNode;
  cell: (item: T) => ReactNode;
  footer?: ReactNode;
  className?: string;
  /** Custom click handler for specific cell, stops propagation if provided */
  onCellClick?: (item: T, e: React.MouseEvent) => void;
  /** Unique ID for the column, required if the column is sortable */
  id?: string;
  /** Whether the column can be sorted */
  sortable?: boolean;
  /** Hàm trích xuất dữ liệu nội bộ (Dành riêng cho Local Sort tự động đối với cột nested) */
  accessor?: (item: T) => string | number | null | undefined;
}

/** Server-side pagination configuration (backward-compatible, optional) */
export interface PaginationConfig<T> {
  /** Paginated result from API containing page, totalPages, total */
  result: PaginatedResult<T> | undefined;
  /** Callback when user navigates to a different page */
  onPageChange: (page: number) => void;
  /** Callback when user changes page size */
  onPageSizeChange?: (size: number) => void;
  /** Custom label for item count, e.g. "cuộn", "đơn hàng". Default: "mục" */
  itemLabel?: string;
}

interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  renderMobileCard: (item: T) => ReactNode;
  isLoading?: boolean;
  /** Skeleton config */
  skeletonRows?: number;
  /** Empty state config */
  emptyStateTitle?: string;
  emptyStateDescription?: string;
  emptyStateIcon?: string;
  emptyStateActionLabel?: string;
  onEmptyStateAction?: () => void;
  /** Row click handler */
  onRowClick?: (item: T) => void;
  /** Additional container classes */
  className?: string;
  rowKey: (item: T) => string | number;
  /** Sort configuration */
  sortColumn?: string;
  sortDirection?: 'asc' | 'desc';
  onSort?: (columnId: string) => void;
  /** Tùy chọn Bật/Tắt tính tự sắp xếp phía Client nếu không cấu hình API Sort (Mặc định: Bật) */
  enableClientSort?: boolean;
  /** Sử dụng giao diện thu gọn, tiết kiệm diện tích */
  density?: 'compact' | 'comfortable';
  /** Giữ cố định header khi cuộn */
  stickyHeader?: boolean;
  /** Thêm sọc vằn (zebra striping) để dễ đọc ngang */
  striped?: boolean;
  /** Server-side pagination config. When provided, pagination bar is rendered below the table. */
  pagination?: PaginationConfig<T>;
  /** DIL Interaction Domain (replaces hardcoded hover indicators) */
  interactionDomain?: InteractionDomain;
}

/**
 * A standardized responsive table component for the ERP Premium UI.
 * Handles Desktop (Table) and Mobile (Card List) views automatically.
 */
function DataTableInner<T>({
  data,
  columns,
  renderMobileCard,
  isLoading = false,
  skeletonRows = 8,
  emptyStateTitle = 'Không tìm thấy dữ liệu',
  emptyStateDescription = 'Hãy thử thay đổi điều kiện lọc hoặc tạo mới.',
  emptyStateIcon = '🔍',
  emptyStateActionLabel,
  onEmptyStateAction,
  onRowClick,
  className,
  rowKey,
  sortColumn,
  sortDirection,
  onSort,
  enableClientSort = true,
  density = 'comfortable',
  stickyHeader = false,
  striped = false,
  pagination,
  interactionDomain,
}: DataTableProps<T>) {
  // --- NATIVE AUTO-SORT LOGIC ---
  const [internalSortCol, setInternalSortCol] = useState<string | undefined>();
  const [internalSortDir, setInternalSortDir] = useState<'asc' | 'desc'>('asc');

  // Ưu tiên Props (Controlled) nếu có, nếu không thì dùng State Nội Bộ (Uncontrolled)
  const activeSortCol = sortColumn !== undefined ? sortColumn : internalSortCol;
  const activeSortDir =
    sortDirection !== undefined ? sortDirection : internalSortDir;

  const handleToggleSort = (colId: string) => {
    if (onSort) {
      onSort(colId); // Trả quyền quyết định về Màn hình (API Sort)
    } else {
      // Tự động sắp xếp nội bộ
      if (activeSortCol === colId) {
        setInternalSortDir((prev) => (prev === 'asc' ? 'desc' : 'asc'));
      } else {
        setInternalSortCol(colId);
        setInternalSortDir('asc');
      }
    }
  };

  // Tự động phân tích dữ liệu mảng và hoán đổi vị trí theo Active State
  const ProcessedData = useMemo(() => {
    if (!enableClientSort || !activeSortCol || onSort) return data; // Nếu màn hình có `onSort`, ta ưu tiên API Data

    return [...data].sort((a, b) => {
      const colDef = columns.find((c) => c.id === activeSortCol);
      // Lấy giá trị so sánh (Dùng accessor nếu có khai báo, nếu không lấy key obj)
      const aVal = colDef?.accessor
        ? colDef.accessor(a)
        : (a as Record<string, unknown>)[activeSortCol];
      const bVal = colDef?.accessor
        ? colDef.accessor(b)
        : (b as Record<string, unknown>)[activeSortCol];

      if (aVal === bVal) return 0;
      if (aVal == null) return activeSortDir === 'asc' ? 1 : -1;
      if (bVal == null) return activeSortDir === 'asc' ? -1 : 1;
      if (aVal < bVal) return activeSortDir === 'asc' ? -1 : 1;
      return activeSortDir === 'asc' ? 1 : -1;
    });
  }, [data, activeSortCol, activeSortDir, enableClientSort, columns, onSort]);
  // ------------------------------

  if (isLoading) {
    return <TableSkeleton rows={skeletonRows} columns={columns.length} />;
  }

  if (data.length === 0) {
    return (
      <div className="py-20">
        <EmptyState
          icon={emptyStateIcon}
          title={emptyStateTitle}
          description={emptyStateDescription}
          actionLabel={emptyStateActionLabel}
          actionClick={onEmptyStateAction}
        />
      </div>
    );
  }

  const hasFooter = columns.some((col) => col.footer !== undefined);

  return (
    <div className={clsx('card-table-section', className)}>
      {/* Desktop View */}
      <div className="hidden md:block overflow-x-auto">
        <table
          className={clsx(
            'data-table',
            density === 'compact' && 'data-table-compact',
          )}
        >
          <thead>
            <tr>
              {columns.map((col, idx) => (
                <th
                  key={col.id || idx}
                  className={clsx(
                    col.className,
                    col.sortable &&
                      'cursor-pointer select-none hover:opacity-80 transition-opacity whitespace-nowrap',
                    stickyHeader &&
                      'sticky top-0 z-10 bg-surface-strong shadow-sm',
                  )}
                  onClick={() => {
                    if (col.sortable && col.id) {
                      handleToggleSort(col.id);
                    }
                  }}
                >
                  <div
                    className={clsx(
                      'flex items-center',
                      col.sortable && 'gap-1',
                    )}
                  >
                    {col.header}
                    {col.sortable && (
                      <span className="shrink-0 flex items-center justify-center">
                        {activeSortCol === col.id ? (
                          activeSortDir === 'asc' ? (
                            <Icon
                              name="ArrowUp"
                              className="w-4 h-4 text-foreground"
                              strokeWidth={1.5}
                            />
                          ) : (
                            <Icon
                              name="ArrowDown"
                              className="w-4 h-4 text-foreground"
                              strokeWidth={1.5}
                            />
                          )
                        ) : (
                          <Icon
                            name="ChevronsUpDown"
                            className="w-4 h-4 text-muted-foreground/50"
                            strokeWidth={1.5}
                          />
                        )}
                      </span>
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {ProcessedData.map((item) => (
              <TableRowInteraction
                key={rowKey(item)}
                interactionDomain={interactionDomain}
                className={clsx(striped && 'even:bg-surface-subtle/30')}
                onClick={onRowClick ? () => onRowClick(item) : undefined}
              >
                {columns.map((col, idx) => (
                  <td
                    key={col.id || idx}
                    className={col.className}
                    onClick={(e) => {
                      if (col.onCellClick) {
                        e.stopPropagation();
                        col.onCellClick(item, e);
                      }
                    }}
                  >
                    {col.cell(item)}
                  </td>
                ))}
              </TableRowInteraction>
            ))}
          </tbody>
          {hasFooter && (
            <tfoot>
              <tr className="bg-surface-subtle font-bold border-t-2 border-border">
                {columns.map((col, idx) => (
                  <td key={col.id || idx} className={col.className}>
                    {col.footer}
                  </td>
                ))}
              </tr>
            </tfoot>
          )}
        </table>
      </div>

      {/* Mobile View */}
      <div className="md:hidden space-y-3 p-3">
        {ProcessedData.map((item) => (
          <div
            key={rowKey(item)}
            className="mobile-card-wrapper"
            onClick={() => onRowClick?.(item)}
          >
            {renderMobileCard(item)}
          </div>
        ))}
      </div>

      {/* Built-in Pagination (only when pagination prop is provided) */}
      {pagination && (
        <Pagination
          result={pagination.result}
          onPageChange={pagination.onPageChange}
          itemLabel={pagination.itemLabel}
          onPageSizeChange={pagination.onPageSizeChange}
        />
      )}
    </div>
  );
}

export const DataTable = memo(DataTableInner) as typeof DataTableInner;

import type { DebtAgingRow } from '@/api/reports.api';
import {
  KpiCard,
  KpiGrid,
  DataTable,
  type DataTableColumn,
  DebtDistributionBar,
} from '@/shared/components';
import { MoneyText } from '@/shared/value';
import { sumBy } from '@/shared/utils/array.util';

type DebtAgingSectionProps = {
  data: DebtAgingRow[];
  isLoading: boolean;
};

const BUCKET_ORDER = ['0-30', '31-60', '61-90', '90+'] as const;
const BUCKET_LABELS: Record<string, string> = {
  '0-30': '0–30 ngày',
  '31-60': '31–60 ngày',
  '61-90': '61–90 ngày',
  '90+': 'Trên 90 ngày',
};
type BucketVariant = 'success' | 'primary' | 'warning' | 'danger' | 'secondary';

const BUCKET_VARIANTS: Record<string, BucketVariant> = {
  '0-30': 'success',
  '31-60': 'primary',
  '61-90': 'warning',
  '90+': 'danger',
};
const BUCKET_COLORS: Record<string, string> = {
  '0-30': 'var(--success)',
  '31-60': 'var(--primary)',
  '61-90': 'var(--warning)',
  '90+': 'var(--danger)',
};

type BucketSummary = {
  bucket: string;
  label: string;
  variant: BucketVariant;
  color: string;
  count: number;
  total: number;
  percent: number;
};

function computeBuckets(data: DebtAgingRow[]): BucketSummary[] {
  const grandTotal = sumBy(data, (r) => r.balance_due);
  return BUCKET_ORDER.map((bucket) => {
    const rows = data.filter((r) => r.aging_bucket === bucket);
    const total = sumBy(rows, (r) => r.balance_due);
    return {
      bucket,
      label: BUCKET_LABELS[bucket] ?? bucket,
      variant: BUCKET_VARIANTS[bucket] ?? 'secondary',
      color: BUCKET_COLORS[bucket] ?? '#888',
      count: rows.length,
      total,
      percent: grandTotal > 0 ? Math.round((total / grandTotal) * 100) : 0,
    };
  });
}

export function DebtAgingSection({ data, isLoading }: DebtAgingSectionProps) {
  const totalDebt = sumBy(data, (r) => r.balance_due);
  const buckets = computeBuckets(data);
  const criticalRows = data.filter((r) => r.aging_bucket === '90+');

  const columns: DataTableColumn<DebtAgingRow>[] = [
    {
      header: 'Đơn hàng',
