import { useState, KeyboardEvent, useRef } from 'react';

import { Icon } from './Icon';

type TagInputProps = {
  value?: string[];
  onChange?: (tags: string[]) => void;
  placeholder?: string;
  hasError?: boolean;
  className?: string;
  id?: string;
};

export function TagInput({
  value = [],
  onChange,
  placeholder = 'Nhập và nhấn Enter...',
  hasError,
  className = '',
  id,
}: TagInputProps) {
  const [inputValue, setInputValue] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleAddTag = (tag: string) => {
    const trimmed = tag.trim();
    if (trimmed && !value.includes(trimmed)) {
      onChange?.([...value, trimmed]);
    }
    setInputValue('');
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      handleAddTag(inputValue);
    } else if (e.key === 'Backspace' && !inputValue && value.length > 0) {
      // Remove last tag if backspace is pressed and input is empty
      onChange?.(value.slice(0, -1));
    }
  };

  const handleRemoveTag = (indexToRemove: number) => {
    onChange?.(value.filter((_, index) => index !== indexToRemove));
  };

  return (
    <div
      className={`field-input flex flex-wrap gap-2 items-center !h-auto min-h-[40px] py-1.5 ${
        hasError ? 'border-danger' : ''
      } ${className}`}
      onClick={() => inputRef.current?.focus()}
    >
      {value.map((tag, index) => (
        <span
          key={tag}
          className="inline-flex items-center gap-1 px-2 py-0.5 bg-surface-strong border border-border rounded-full text-sm font-medium text-text transition-colors hover:bg-red-50 hover:border-danger hover:text-danger group cursor-pointer"
          onClick={(e) => {
            e.stopPropagation();
            handleRemoveTag(index);
          }}
        >
          {tag}
          <Icon
            name="X"
            size={12}
            className="text-muted group-hover:text-danger"
          />
        </span>
      ))}

      <input
        ref={inputRef}
        id={id}
        type="text"
        className="flex-1 min-w-[120px] bg-transparent border-none outline-none p-0 text-sm"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => {
          if (inputValue.trim()) {
            handleAddTag(inputValue);
          }
        }}
        placeholder={value.length === 0 ? placeholder : ''}
      />
    </div>
  );
}

import { clsx } from 'clsx';
import type { ReactNode } from 'react';

import { Icon, type IconName } from './Icon';

export interface TimelineStep {
  id: string;
  title: string;
  subtitle?: string | ReactNode;
  icon?: IconName;
  status: 'completed' | 'current' | 'pending' | 'error';
  date?: string;
}

interface TimelineProgressProps {
  steps: TimelineStep[];
  className?: string;
  direction?: 'vertical' | 'horizontal';
}

/**
 * Premium Timeline Progress Component
 * Displays a vertical step-by-step timeline, perfect for Order tracking and Production flow.
 */
export function TimelineProgress({
  steps,
  className,
  direction = 'vertical',
}: TimelineProgressProps) {
  return (
    <div
      className={clsx(
        'flex w-full',
        direction === 'vertical'
          ? 'flex-col gap-0'
          : 'flex-row items-start justify-between gap-4 overflow-x-auto pb-4 scrollbar-none',
        className,
      )}
    >
      {steps.map((step, idx) => {
        const isLast = idx === steps.length - 1;
        const IconName = step.icon ?? 'Circle';

        // Colors mapping based on status
        const activeColor = {
          completed: 'bg-success text-inverse border-success',
          current:
            'bg-surface border-primary text-primary shadow-[0_0_8px_var(--primary)]',
          pending: 'bg-surface border-border text-muted',
          error: 'bg-danger text-inverse border-danger',
        }[step.status];

        const lineColorClass = {
          completed: 'bg-success',
          current: 'border-dashed border-border', // Rendered as border-l-2
          pending: 'bg-border',
          error: 'bg-danger',
        }[step.status];

        return (
          <div
            key={step.id}
            className={clsx(
              'relative group fade-up',
              direction === 'vertical'
                ? 'flex items-start gap-4'
                : 'flex flex-col items-center flex-1 min-w-[140px]',
            )}
            style={{ animationDelay: `${idx * 0.1}s` }}
          >
            {/* Timeline line connecting steps */}
            {!isLast && (
              <div
                className={clsx(
                  'absolute transition-colors duration-500',
                  direction === 'vertical'
                    ? 'left-4 top-8 bottom-[-16px] w-[2px] -translate-x-1/2'
                    : 'top-4 left-[50%] right-[-50%] h-[2px]',
                  step.status === 'current'
                    ? (direction === 'vertical' ? 'border-l-2' : 'border-t-2') +
                        ' border-dashed border-border bg-transparent'
                    : lineColorClass,
                )}
              />
            )}

            {/* Step Icon Node */}
            <div
              className={clsx(
                'relative z-10 flex flex-col items-center',
                direction === 'horizontal' && 'mb-3',
              )}
            >
              <div
                className={clsx(
                  'w-8 h-8 rounded-full border-2 flex items-center justify-center shrink-0 transition-transform duration-300 group-hover:scale-110',
                  activeColor,
                )}
              >
                {step.status === 'completed' ? (
                  <Icon name="Check" size={16} strokeWidth={3} />
                ) : (
                  <Icon name={IconName} size={14} strokeWidth={2.5} />
                )}
              </div>
            </div>

            {/* Step Content */}
            <div
              className={clsx(
                'transition-all duration-300',
                direction === 'vertical'
                  ? 'flex-1 mb-6 p-4 rounded-xl border'
                  : 'flex flex-col items-center text-center p-3 rounded-lg border w-full relative group-hover:shadow-md',
                step.status === 'completed' &&
                  'bg-success/10 border-success/20',
                step.status === 'current' &&
                  'bg-primary/10 border-primary/30 shadow-sm',
                step.status === 'error' && 'bg-danger/10 border-danger/20',
                step.status === 'pending' &&
                  'bg-transparent border-transparent pt-1 px-0',
              )}
            >
              <div
                className={clsx(
                  'flex',
                  direction === 'vertical'
                    ? 'justify-between items-start gap-2'
                    : 'flex-col items-center gap-1.5',
                )}
              >
                <div
                  className={clsx(
                    direction === 'horizontal' &&
                      'flex flex-col items-center w-full',
                  )}
                >
                  <h4
                    className={clsx(
                      'text-sm font-bold m-0',
                      step.status === 'completed' && 'text-success-700',
                      step.status === 'current' && 'text-primary-700',
                      step.status === 'error' && 'text-danger-700',
                      step.status === 'pending' && 'text-muted',
                    )}
                  >
                    {step.title}
                  </h4>
                  {step.subtitle && (
                    <div
                      className={clsx(
                        direction === 'vertical'
                          ? 'text-xs mt-1 leading-relaxed'
                          : 'text-[11px] leading-tight mt-1 px-1',
                        step.status === 'pending'
                          ? 'text-muted'
                          : 'text-text/80',
                      )}
                    >
                      {step.subtitle}
                    </div>
                  )}
                </div>
                {step.date && (
                  <div
                    className={clsx(
                      'font-semibold uppercase tracking-wider tabular-nums whitespace-nowrap',
                      direction === 'vertical'
                        ? 'text-[10px] pt-0.5'
                        : 'text-[9px] mt-1',
                      step.status === 'pending' ? 'text-muted' : 'text-text/60',
                    )}
                  >
                    {step.date}
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

import React, {
  useState,
  useMemo,
  forwardRef,
  useImperativeHandle,
  useRef,
  useEffect,
} from 'react';

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { cn } from '@/shared/utils/cn';
import { Icon } from '@/shared/components';

export interface VPBaseComboboxRef {
  open: () => void;
  close: () => void;
  focus: () => void;
  clear: () => void;
}

export interface VPBaseComboboxProps<T> {
  options: T[];
  value?: string;
  onChange: (value: string) => void;

  getOptionValue: (option: T) => string;
  getOptionLabel: (option: T) => string;

  renderValue?: (option: T | undefined) => React.ReactNode;

  searchFn?: (option: T, keyword: string) => boolean;
  searchPlaceholder?: string;
  searchValue?: string;
  onSearchChange?: (search: string) => void;

  disabled?: boolean;
  loading?: boolean;
  hasError?: boolean;
  placeholder?: string;
  emptyText?: React.ReactNode;

  headerSlot?: React.ReactNode;
  footerSlot?: React.ReactNode;

  className?: string;
  id?: string;

  renderList: (props: {
    filteredOptions: T[];
    focusedIndex: number;
    onSelect: (option: T) => void;
    setFocusedIndex: (index: number) => void;
  }) => React.ReactNode;
}

export const VPBaseCombobox = forwardRef(
  <T,>(
    {
      options,
      value,
      onChange,
      getOptionValue,
      getOptionLabel,
      renderValue,
      searchFn,
      searchPlaceholder = 'Tìm kiếm...',
      searchValue,
      onSearchChange,
      disabled,
      loading,
      hasError,
      placeholder = 'Chọn...',
      emptyText = 'Không có kết quả.',
      headerSlot,
      footerSlot,
      className,
      id,
      renderList,
    }: VPBaseComboboxProps<T>,
    ref: React.ForwardedRef<VPBaseComboboxRef>,
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [internalSearch, setInternalSearch] = useState('');
    const [focusedIndex, setFocusedIndex] = useState(-1);
    const triggerRef = useRef<HTMLButtonElement>(null);

    const search = searchValue !== undefined ? searchValue : internalSearch;

    const handleSearchChange = (val: string) => {
      if (searchValue === undefined) {
        setInternalSearch(val);
      }
      onSearchChange?.(val);
      setFocusedIndex(0); // Reset focus on search
    };

    // Reset search when popover closes (Bug 1)
    useEffect(() => {
      if (!isOpen) {
        if (searchValue === undefined) {
          setInternalSearch('');
        }
        onSearchChange?.('');
      }
    }, [isOpen, searchValue, onSearchChange]);

    const filteredOptions = useMemo(() => {
      if (!search) return options;
      const lowerSearch = search.toLowerCase();
      return options.filter((opt) => {
        if (searchFn) return searchFn(opt, lowerSearch);
        return getOptionLabel(opt).toLowerCase().includes(lowerSearch);
      });
    }, [options, search, searchFn, getOptionLabel]);

    // Sync selected option
    const selectedOption = useMemo(
      () => options.find((opt) => getOptionValue(opt) === value),
      [options, value, getOptionValue],
    );

    useImperativeHandle(ref, () => ({
      open: () => setIsOpen(true),
      close: () => setIsOpen(false),
      focus: () => triggerRef.current?.focus(),
      clear: () => onChange(''),
    }));

    const handleSelect = (option: T) => {
      const val = getOptionValue(option);
      onChange(val === value ? '' : val); // toggle
      setIsOpen(false);
      handleSearchChange('');
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (filteredOptions.length === 0) return;

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          setFocusedIndex((prev) =>
            prev < filteredOptions.length - 1 ? prev + 1 : prev,
          );
          break;
        case 'ArrowUp':
          e.preventDefault();
          setFocusedIndex((prev) => (prev > 0 ? prev - 1 : 0));
          break;
        case 'Enter':
          e.preventDefault();
          if (focusedIndex >= 0 && focusedIndex < filteredOptions.length) {
            const opt = filteredOptions[focusedIndex];
            if (opt) handleSelect(opt);
          }
          break;
        case 'Home':
          e.preventDefault();
          setFocusedIndex(0);
          break;
        case 'End':
          e.preventDefault();
          setFocusedIndex(filteredOptions.length - 1);
          break;
      }
    };

    // Reset focus when opening
    useEffect(() => {
      if (isOpen) {
        const initialIndex = filteredOptions.findIndex(
          (opt) => getOptionValue(opt) === value,
        );
        setFocusedIndex(initialIndex >= 0 ? initialIndex : 0);
      } else {
        setFocusedIndex(-1);
      }
    }, [isOpen, value, filteredOptions, getOptionValue]);

    const activeDescendantId =
      focusedIndex >= 0 ? `vp-combo-opt-${focusedIndex}` : undefined;

    return (
      <Popover open={isOpen} onOpenChange={setIsOpen} modal={false}>
        <PopoverTrigger asChild>
          <button
            id={id}
            ref={triggerRef}
            type="button"
            disabled={disabled || loading}
            role="combobox"
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            aria-controls="vp-combo-listbox"
            className={cn(
              'flex h-10 w-full items-center justify-between rounded-md border bg-surface px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-1 disabled:cursor-not-allowed disabled:opacity-50',
              hasError ? 'border-danger' : 'border-border',
              className,
            )}
          >
            <div className="flex flex-1 items-center gap-2 truncate text-left">
              {loading && (
                <Icon
                  name="Loader2"
                  className="h-4 w-4 animate-spin opacity-50"
                />
              )}
              {selectedOption ? (
                renderValue ? (
                  renderValue(selectedOption)
                ) : (
                  <span className="truncate">
                    {getOptionLabel(selectedOption!)}
                  </span>
                )
              ) : (
                <span className="text-muted truncate">{placeholder}</span>
              )}
            </div>
            <Icon
              name="ChevronDown"
              className="ml-2 h-4 w-4 shrink-0 opacity-50"
            />
          </button>
        </PopoverTrigger>

        <PopoverContent
          className="w-[var(--radix-popover-trigger-width)] p-0"
          align="start"
          onKeyDown={handleKeyDown}
        >
          <div className="flex flex-col h-full max-h-[400px]">
            {headerSlot && <div className="border-b">{headerSlot}</div>}

            <div className="flex items-center border-b px-3 shrink-0">
              <Icon
                name="Search"
                className="mr-2 h-4 w-4 shrink-0 opacity-50"
              />
              <input
                className="flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
                placeholder={searchPlaceholder}
                value={search}
                onChange={(e) => handleSearchChange(e.target.value)}
                aria-activedescendant={activeDescendantId}
                autoFocus // (Bug 3)
              />
            </div>

            <div
              id="vp-combo-listbox"
              role="listbox"
              className="flex-1 overflow-y-auto"
              style={{ maxHeight: '250px' }}
            >
              {filteredOptions.length === 0 ? (
                <div className="py-6 text-center text-sm text-muted">
                  {loading ? ( // (Bug 6)
                    <span className="flex items-center justify-center gap-2">
                      <Icon
                        name="Loader2"
                        className="h-4 w-4 animate-spin opacity-50"
                      />
                      Đang tải...
                    </span>
                  ) : (
                    emptyText
                  )}
                </div>
              ) : (
                renderList({
                  filteredOptions,
                  focusedIndex,
                  onSelect: handleSelect,
                  setFocusedIndex,
                })
              )}
            </div>

            {footerSlot && <div className="border-t">{footerSlot}</div>}
          </div>
        </PopoverContent>
      </Popover>
    );
  },
);

VPBaseCombobox.displayName = 'VPBaseCombobox';

// Cast for generics
export type VPBaseComboboxComponent = <T>(
  props: VPBaseComboboxProps<T> & {
    ref?: React.ForwardedRef<VPBaseComboboxRef>;
  },
) => React.ReactElement;

export const VPBaseComboboxGeneric = VPBaseCombobox as VPBaseComboboxComponent;

/**
 * Field Renderers Registry (Strategy Pattern)
 *
 * Registry Pattern mapping field types to their React rendering implementations.
 * Resolves Open/Closed Principle (OCP) violation: To add a new filter type,
 * you simply register it here without touching the main component logic.
 */

import { Combobox } from '@/shared/components/Combobox';
import { UI_LABELS } from '@/shared/constants/ui.constants';

import { DebouncedSearchInput } from './DebouncedSearchInput';
import { FilterDateInput } from './FilterDateInput';
import {
  FieldRenderersRegistry,
  isSearchFilterField,
  isComboboxFilterField,
  isDateRangeFilterField,
} from './types';

/**
 * Registry của tất cả field renderers.
 * Mỗi field type có một React component tương ứng.
 */
export const FieldRenderers: FieldRenderersRegistry = {
  search: ({ field, value, onChange, idPrefix }) => {
    if (!isSearchFilterField(field)) return null;
    const inputId = `${idPrefix}${field.key}`;
    return (
      <div className="filter-field">
        <label htmlFor={inputId}>{field.label}</label>
        <DebouncedSearchInput
          id={inputId}
          fieldKey={field.key}
          placeholder={
            field.placeholder ||
            `${UI_LABELS.SEARCH_PLACEHOLDER.replace('...', '')} ${field.label.toLowerCase()}...`
          }
          initialValue={value[field.key] || ''}
          onChange={onChange}
        />
      </div>
    );
  },

  combobox: ({ field, value, onChange, idPrefix }) => {
    if (!isComboboxFilterField(field)) return null;
    // A11Y: Combobox dùng <button> trigger — không thể dùng htmlFor.
    const labelId = `${idPrefix}label-${field.key}`;
    return (
      <div className="filter-field">
        <label id={labelId}>{field.label}</label>
        <Combobox
          aria-labelledby={labelId}
          options={[
            {
              value: '',
              label: `${UI_LABELS.ALL} ${field.label.toLowerCase()}`,
            },
            ...field.options,
          ]}
          value={(value[field.key] as string) ?? ''}
          onChange={(val) => onChange(field.key, val || undefined)}
        />
      </div>
    );
  },

  date: ({ field, value, onChange, idPrefix }) => (
    <div className="filter-field">
      <FilterDateInput
        id={`${idPrefix}${field.key}`}
        label={field.label}
        value={(value[field.key] as string) ?? ''}
        onChange={(val) => onChange(field.key, val)}
      />
    </div>
  ),

  date_range: ({ field, value, onChange, idPrefix }) => {
    if (!isDateRangeFilterField(field)) return null;
    return (
      <div className="filter-field flex-[1_1_280px]">
        <label>{field.label}</label>
        <div className="flex items-end gap-2">
          <FilterDateInput
            id={`${idPrefix}${field.keyFrom}`}
            label={field.labelFrom ?? UI_LABELS.FROM_DATE}
            value={(value[field.keyFrom] as string) ?? ''}
            onChange={(val) => onChange(field.keyFrom, val)}
          />
          <span className="text-muted mb-[10px] flex-shrink-0">→</span>
          <FilterDateInput
            id={`${idPrefix}${field.keyTo}`}
            label={field.labelTo ?? UI_LABELS.TO_DATE}
            value={(value[field.keyTo] as string) ?? ''}
            onChange={(val) => onChange(field.keyTo, val)}
          />
        </div>
      </div>
    );
  },
};

import React, { forwardRef } from 'react';

import { Icon } from '@/shared/components/Icon';
import { calcDeviationPercent } from '@/features/raw-fabric/helpers';
import { cn } from '@/shared/utils/cn';

import { AnomalyStatus } from './useRollMatrixLogic';

export type RollGridItemMode = 'input' | 'view' | 'select';

interface RollGridItemProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  'value' | 'onChange'
> {
  mode?: RollGridItemMode;
  label?: string; // e.g., "R01" or the roll number
  /** Secondary label shown below main label (e.g., raw roll number for pairing) */
  subLabel?: string;
  value?: number;
  /** Unit label shown after value (default: "kg") */
  valueUnit?: string;
  anomalyStatus?: AnomalyStatus;
  isGhost?: boolean;
  /** Whether this cell is currently selected (mode=select) */
  isSelected?: boolean;
  statusIcon?: 'locked' | 'cut' | 'none'; // Further visual signals
  onChangeWeight?: (weight: number | undefined) => void;
  onPress?: () => void; // Mobile friendly tap handler
  /** Standard weight in kg — used to compute deviation tooltip for light/heavy anomalies */
  standardWeightKg?: number;
  /** Product thumbnail URL (shown as background in view/select mode) */
  imageUrl?: string | null;
}

/** Simple Tailwind-based tooltip wrapper */
function Tooltip({
  content,
  children,
}: {
  content: string;
  children: React.ReactNode;
}) {
  return (
    <span className="relative group/tip">
      {children}
      <span
        className={cn(
          'pointer-events-none absolute bottom-full left-1/2 -translate-x-1/2 mb-1 z-50',
          'whitespace-nowrap rounded px-2 py-1 text-[10px] font-semibold',
          'bg-surface-strong text-inverse shadow-lg',
          'opacity-0 group-hover/tip:opacity-100 transition-opacity duration-150',
        )}
      >
        {content}
      </span>
    </span>
  );
}

export const RollGridItem = forwardRef<HTMLInputElement, RollGridItemProps>(
  (
    {
      mode = 'view',
      label,
      subLabel,
      value,
      valueUnit = 'kg',
      anomalyStatus = 'normal',
      isGhost = false,
      isSelected = false,
      statusIcon = 'none',
      onChangeWeight,
      onPress,
      className,
      standardWeightKg,
      imageUrl,
      ...props
    },
    ref,
  ) => {
    // Determine color codes based on Anomaly - Premium Professional Palette
    const anomalyStyles = {
      normal: {
        bg: 'var(--surface-strong)',
        text: 'var(--text)',
        border: 'var(--border)',
        shadow: '0 2px 8px rgba(0,0,0,0.04)',
      },
      light: {
        bg: 'rgba(225, 29, 72, 0.08)',
        text: '#be123c',
        border: 'rgba(225, 29, 72, 0.4)',
        shadow: '0 4px 12px rgba(225, 29, 72, 0.12)',
      },
      heavy: {
        bg: 'rgba(217, 119, 6, 0.08)',
        text: '#b45309',
        border: 'rgba(217, 119, 6, 0.4)',
        shadow: '0 4px 12px rgba(217, 119, 6, 0.12)',
      },
      empty: {
        bg: 'rgba(16, 35, 61, 0.02)',
        text: 'var(--muted)',
        border: 'var(--border)',
        shadow: 'none',
      },
    };

    const currentStyle = isGhost
      ? anomalyStyles.empty
      : anomalyStyles[anomalyStatus];

    const isCompact = mode === 'view';

    const baseClass = cn(
      'relative flex flex-col justify-center items-center transition-all duration-200 rounded-[var(--radius-sm)]',
      isCompact
        ? 'p-1.5 min-h-[44px] min-w-[44px]'
        : 'p-3 min-h-[72px] min-w-[64px]',
      mode === 'select' && isSelected ? 'scale-[1.02] z-10' : '',
      mode !== 'input'
        ? 'cursor-pointer hover:border-primary active:scale-95 select-none'
        : 'focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/10',
      className,
    );

    const renderIcon = () => {
      if (mode === 'select' && isSelected) {
        return (
          <span className="absolute -top-1.5 -right-1.5 w-6 h-6 bg-success-soft rounded-full flex items-center justify-center shadow-lg border-2 border-transparent animate-in zoom-in-50 duration-200">
            <Icon name="Check" size={14} className="text-inverse" />
          </span>
        );
      }

      if (statusIcon === 'locked')
        return (
          <div className="absolute top-1 right-1 p-0.5 rounded-[var(--radius-sm)] text-[var(--text-muted)] bg-[var(--surface-subtle)] opacity-80">
            <Icon name="Lock" size={10} />
          </div>
        );
      if (statusIcon === 'cut')
        return (
          <div className="absolute top-1 right-1 p-0.5 rounded-[var(--radius-sm)] text-[var(--text-muted)] bg-[var(--surface-subtle)] opacity-80">
            <Icon name="Scissors" size={10} />
          </div>
        );
      return null;
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!onChangeWeight) return;
      const valStr = e.target.value;
      if (!valStr) {
        onChangeWeight(undefined);
        return;
      }
      const num = parseFloat(valStr);
      if (isNaN(num)) {
        onChangeWeight(undefined);
        return;
      }
      onChangeWeight(num);
    };

    const processFastEntry = () => {
      if (value !== undefined && value >= 100) {
        if (!String(value).includes('.')) {
          onChangeWeight?.(value / 100);
        }
      }
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      processFastEntry();
      props.onBlur?.(e);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        processFastEntry();
      }
      props.onKeyDown?.(e);
    };

    const displayValue = () => {
      if (isGhost) return '';
      if (!value)
        return (
          <span
            className={cn(
              'opacity-30',
              isCompact ? 'text-[10px]' : 'text-[14px]',
            )}
          >
            -
          </span>
        );
      if (isCompact) {
        // Compact: show value only, no unit suffix to save space
        return (
          <span className="text-[11px] font-extrabold tracking-[-0.02em] leading-none">
            {value}
          </span>
        );
      }
      return (
        <span className="flex items-baseline gap-0.5">
          <span className="text-base font-black tracking-tight">{value}</span>
          <span className="text-[9px] font-bold opacity-60 uppercase">
            {valueUnit}
          </span>
        </span>
      );
    };

    // Compute anomaly tooltip text when light/heavy and standardWeightKg is provided
    const anomalyTooltip = (() => {
      if (
        !standardWeightKg ||
        (anomalyStatus !== 'light' && anomalyStatus !== 'heavy')
      )
        return null;
      if (value === undefined) return null;
      const pct = calcDeviationPercent(value, standardWeightKg).toFixed(1);
      return anomalyStatus === 'light'
        ? `Nhẹ hơn chuẩn ${pct}%`
        : `Nặng hơn chuẩn ${pct}%`;
    })();

    // Build tooltip content — include subLabel (raw roll number) for traceability
    const labelTooltipContent = subLabel
      ? `${label} | Moc: ${subLabel}`
      : (label ?? '');

    // Render label — truncate + tooltip when > 8 chars or has subLabel
    const renderLabel = () => {
      if (!label) return null;
      // Compact view: show truncated label with tooltip always
      if (isCompact) {
        const shortLabel = label.length > 6 ? label.slice(-5) : label;
        return (
          <Tooltip content={labelTooltipContent}>
            <span className="text-[8px] font-bold opacity-60 leading-none tracking-[0.02em] uppercase block text-center overflow-hidden whitespace-nowrap max-w-full">
              {shortLabel}
            </span>
          </Tooltip>
        );
      }
      const labelSpan = (
        <span
          className={cn(
            'uppercase font-extrabold opacity-70 leading-none mb-0.5 truncate max-w-full',
            'text-[10px]',
            label.length > 8 ? 'block' : '',
            anomalyStatus === 'empty' ? 'opacity-30' : '',
          )}
        >
          {label}
        </span>
      );

      if (label.length > 8 || subLabel) {
        return <Tooltip content={labelTooltipContent}>{labelSpan}</Tooltip>;
      }
      return labelSpan;
    };

    const cellContent = (
      <div
        className={baseClass}
        onClick={mode !== 'input' ? onPress : undefined}
        style={{
          borderRadius: 'var(--radius-md)',
          border: isSelected
            ? '2px solid #10b981'
            : isGhost
              ? '1px dashed var(--border)'
              : `1.5px solid ${currentStyle.border}`,
          background: isSelected ? 'rgba(16, 185, 129, 0.08)' : currentStyle.bg,
          boxShadow: isSelected
            ? '0 8px 20px rgba(16, 185, 129, 0.15)'
            : isCompact
              ? 'none'
              : currentStyle.shadow,
          color: isSelected ? '#064e3b' : currentStyle.text,
          opacity: isGhost ? 0.4 : 1,
          ...(isCompact
            ? {
                height: 44,
                borderRadius: 6,
              }
            : {}),
        }}
      >
        {/* Thumbnail background (view/select mode only) */}
        {imageUrl && mode !== 'input' && (
          <img
            src={imageUrl}
            alt=""
            className="absolute inset-0 w-full h-full object-cover rounded-[inherit] opacity-20"
            loading="lazy"
          />
        )}
        {renderLabel()}

        {/* subLabel (raw roll number) is merged into label tooltip for space efficiency */}

        <div className="flex-1 flex items-center justify-center w-full">
          {mode === 'input' ? (
            <input
              {...props}
              ref={ref}
              type="number"
              step="0.1"
              className="w-full text-center bg-transparent border-none outline-none font-black text-base focus:ring-0 p-0 m-0"
              style={{ color: 'inherit' }}
              value={value ?? ''}
              onChange={handleInputChange}
              onBlur={handleBlur}
              onKeyDown={handleKeyDown}
              placeholder="..."
            />
          ) : (
            <div className="text-center">{displayValue()}</div>
          )}
        </div>

        {renderIcon()}
      </div>
    );

    // Wrap entire cell in anomaly tooltip when applicable
    if (anomalyTooltip) {
      return <Tooltip content={anomalyTooltip}>{cellContent}</Tooltip>;
    }

    return cellContent;
  },
);

RollGridItem.displayName = 'RollGridItem';

